//! Rigged peon bodies: one skinned glTF per life stage (`assets/models/peon_*.glb`, generated by
//! `assets/blender/make_peons.py`), posed on the CPU from the sim's [`Posture`] and drawn with the
//! renderer's skinned path. Each file holds the body, the head, every garment, hair style and
//! facial hair as separate meshes sharing the skeleton. Appearance picks the meshes, drives the
//! palette (skin, hair, clothes, eyes), the morph targets (build plus every face and body slider)
//! and a height scale; skin under the chosen clothes is hidden by region.

use std::collections::HashMap;

use glam::{Mat4, Quat, Vec3};
use hearth_render::model::{Model, Pose as JointPose};
use hearth_render::{PALETTE_SLOTS, Renderer, SkinnedDraw, SkinnedMeshId};
use sim::components::{Appearance, Personality, Posture};
use sim::Entity;
use sim::data::{Hand, LifeStage, Pose};

/// Palette slots, matched to material names in the glTF files.
pub mod slot {
    pub const SKIN: u32 = 1;
    pub const HAIR: u32 = 2;
    pub const SHIRT: u32 = 3;
    pub const PANTS: u32 = 4;
    pub const SHOES: u32 = 5;
    pub const IRIS: u32 = 6;
}

/// Skin regions the body's faces are tagged with (`skin.rN` materials), hidden under clothes.
pub mod region {
    pub const CHEST: u32 = 1;
    pub const BELLY: u32 = 2;
    pub const SHOULDER: u32 = 3;
    pub const UPPER_ARM: u32 = 4;
    pub const FOREARM: u32 = 5;
    pub const PELVIS: u32 = 6;
    pub const THIGH: u32 = 7;
    pub const KNEE: u32 = 8;
    pub const SHIN: u32 = 9;
    pub const FOOT: u32 = 10;
}

/// Skin regions a garment covers (matches `GARMENTS` in `assets/blender/peon_body.py`).
fn covers(garment: &str) -> &'static [u32] {
    use region::*;
    match garment {
        "top_tee" => &[CHEST, BELLY, SHOULDER],
        "top_long" => &[CHEST, BELLY, SHOULDER, UPPER_ARM, FOREARM],
        "top_tank" => &[CHEST, BELLY],
        "top_dress" => &[CHEST, BELLY, PELVIS],
        "bottom_trousers" => &[PELVIS, THIGH, KNEE, SHIN],
        "bottom_shorts" => &[PELVIS, THIGH],
        "bottom_skirt" => &[PELVIS],
        "shoes" => &[FOOT],
        _ => &[],
    }
}

/// Palette slot of a material name, plus its skin region in bits 8.. (`skin.r3`: skin, region 3;
/// `skin.lips`: skin tint, always drawn).
fn slot_of(material: &str) -> u32 {
    let (base, sub) = material.split_once('.').unwrap_or((material, ""));
    let slot = match base {
        "skin" => slot::SKIN,
        "hair" => slot::HAIR,
        "shirt" => slot::SHIRT,
        "pants" => slot::PANTS,
        "shoes" => slot::SHOES,
        "iris" => slot::IRIS,
        _ => 0,
    };
    let region = sub.strip_prefix('r').and_then(|n| n.parse::<u32>().ok()).unwrap_or(0);
    slot | region << 8
}

macro_rules! glb {
    ($name:literal) => {
        ($name, include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../assets/models/peon_", $name, ".glb")).as_slice())
    };
}
const FILES: [(&str, &[u8]); 6] = [glb!("infant"), glb!("toddler"), glb!("child"), glb!("teen"), glb!("adult"), glb!("elder")];

fn file_index(stage: LifeStage) -> usize {
    match stage {
        LifeStage::Infant => 0,
        LifeStage::Toddler => 1,
        LifeStage::Child => 2,
        LifeStage::Teen => 3,
        LifeStage::YoungAdult | LifeStage::Adult => 4,
        LifeStage::Elder => 5,
    }
}

/// One uploaded mesh and its morph target names (index = morph slot).
struct Part {
    mesh: SkinnedMeshId,
    morphs: Vec<String>,
}

struct StageArt {
    model: Model,
    body: Part,
    head: Part,
    /// Garments, hair (`hair.<id>`) and facial hair (`facial.<id>`) by mesh name.
    parts: HashMap<String, Part>,
    /// Rest-pose height of the model and of its head joint (for label placement).
    height: f32,
    head_joint: Option<usize>,
    head_rest_y: f32,
    /// Per hand (right, left): the joint and the grip frame relative to it (see `PropDef`).
    grips: [Option<(usize, Mat4)>; 2],
    rig: Rig,
}

/// Joints the procedural layer moves, and how the skeleton changes with the body's frame.
#[derive(Clone, Debug, Default)]
struct Rig {
    hips: Option<usize>,
    spine: Option<usize>,
    chest: Option<usize>,
    neck: Option<usize>,
    head: Option<usize>,
    /// (joint, offset in its parent's space per unit of masculine frame): shoulders out, hip
    /// joints in. Feminine frames (negative) get the reverse: narrower shoulders, wider pelvis.
    frame: Vec<(usize, Vec3)>,
}

impl Rig {
    fn new(skel: &hearth_render::model::Skeleton, height: f32) -> Rig {
        let j = |n: &str| skel.joint(n);
        let globals = skel.globals(&skel.rest_pose());
        let mut frame = Vec::new();
        // model space: +x is the body's left (`.L`)
        for (name, side, amount) in [("upper_arm.L", 1.0, 0.016), ("upper_arm.R", -1.0, 0.016), ("thigh.L", 1.0, -0.011), ("thigh.R", -1.0, -0.011)] {
            let Some(i) = j(name) else { continue };
            let Some(parent) = skel.joints[i].parent else { continue };
            let to_local = globals[parent].inverse();
            frame.push((i, to_local.transform_vector3(Vec3::X * side * amount * height)));
        }
        Rig { hips: j("hips"), spine: j("spine"), chest: j("chest"), neck: j("neck"), head: j("head"), frame }
    }
}
/// The grip frame of a hand in the rest pose, relative to the hand joint: origin in the palm, +y
/// along the bone, +z towards the body's forward (+z) made perpendicular to the bone.
fn grip_offset(skel: &hearth_render::model::Skeleton, joint: usize, height: f32) -> Mat4 {
    let g = skel.globals(&skel.rest_pose())[joint];
    let y = g.y_axis.truncate().normalize();
    let z = (Vec3::Z - y * y.dot(Vec3::Z)).normalize();
    let x = y.cross(z);
    let palm = g.w_axis.truncate() + y * height * 0.035;
    let rest = Mat4::from_cols(x.extend(0.0), y.extend(0.0), z.extend(0.0), palm.extend(1.0));
    g.inverse() * rest
}

/// How a peon carries themselves when not doing anything in particular (idle and walk variants).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Demeanor {
    #[default]
    Normal,
    /// Bad mood: slumped shoulders, dragging feet.
    Sad,
    /// Theatrical or vain and in a good mood: chin up, strutting.
    Proud,
    /// Paranoid: glances over the shoulder.
    Nervous,
}

impl Demeanor {
    pub fn of(mood: f32, p: Option<&Personality>) -> Demeanor {
        let has = |t: &str| p.is_some_and(|p| p.has(t));
        if mood < -35.0 {
            Demeanor::Sad
        } else if has("paranoid") {
            Demeanor::Nervous
        } else if (has("theatrical") || has("vain")) && mood > 15.0 {
            Demeanor::Proud
        } else {
            Demeanor::Normal
        }
    }
}

/// What a drawn body reports back: the height of the crown above the root (for labels), whether
/// it is playing the interaction's own clip, and the world-space grip frame of each hand (right,
/// left) for props.
#[derive(Clone, Copy, Debug)]
pub struct Drawn {
    pub crown: f32,
    pub acting: bool,
    pub grips: [Mat4; 2],
}

impl Drawn {
    /// Where to draw a prop held in `hand`; None when the body fell back to a generic pose clip
    /// (an infant "reading"), whose hands aren't posed to hold anything.
    pub fn grip(&self, hand: Hand) -> Option<Mat4> {
        self.acting.then(|| {
            self.grips[match hand {
                Hand::Right => 0,
                Hand::Left => 1,
            }]
        })
    }
}

/// How to draw a body.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub enum Look {
    #[default]
    Normal,
    /// Translucent, glowing, pale (the dead walking the lot).
    Ghost,
}

pub struct PeonArt {
    stages: Vec<StageArt>,
}

impl PeonArt {
    /// Parses the embedded models and uploads their meshes.
    pub fn load(r: &mut Renderer) -> anyhow::Result<PeonArt> {
        let mut stages = Vec::with_capacity(FILES.len());
        for (name, bytes) in FILES {
            let model = Model::load_glb(bytes, &slot_of).map_err(|e| anyhow::anyhow!("peon_{name}.glb: {e}"))?;
            let mut parts = HashMap::new();
            for m in &model.meshes {
                parts.insert(m.name.clone(), Part { mesh: r.upload_skinned_mesh(&m.data), morphs: m.morph_names.clone() });
            }
            let body = parts.remove("body").ok_or_else(|| anyhow::anyhow!("peon_{name}.glb: no body mesh"))?;
            let head = parts.remove("head").ok_or_else(|| anyhow::anyhow!("peon_{name}.glb: no head mesh"))?;
            let height = ["body", "head"].iter().filter_map(|n| model.mesh(n)).flat_map(|m| m.data.vertices.iter().map(|v| v.pos[1])).fold(0.0, f32::max);
            let head_joint = model.skeleton.joint("head");
            let head_rest_y = head_joint.map_or(height, |j| model.skeleton.globals(&model.skeleton.rest_pose())[j].w_axis.y);
            let grips = ["hand.R", "hand.L"].map(|n| model.skeleton.joint(n).map(|j| (j, grip_offset(&model.skeleton, j, height))));
            let rig = Rig::new(&model.skeleton, height);
            stages.push(StageArt { model, body, head, parts, height, head_joint, head_rest_y, grips, rig });
        }
        Ok(PeonArt { stages })
    }

    /// Adds a posed body to a frame's `skinned` draws and `joints`. `t` is a per-peon clock in
    /// seconds; `anim` carries the peon's playback between frames (a fresh [`AnimState`] poses it
    /// straight from `t`, with no blending).
    #[allow(clippy::too_many_arguments)]
    pub fn draw(&self, out: (&mut Vec<SkinnedDraw>, &mut Vec<Mat4>), pos: Vec3, yaw: f32, stage: LifeStage, app: &Appearance, posture: &Posture, demeanor: Demeanor, anim: &mut AnimState, t: f32, look: Look) -> Drawn {
        let fi = file_index(stage);
        let art = &self.stages[fi];
        let (clip, rate) = clip_for(&art.model, stage, posture, demeanor, art.height);
        let acting = posture.anim.as_deref() == Some(clip);
        let skel = &art.model.skeleton;
        let dt = (t - anim.last_t).clamp(0.0, 0.25);
        let (pos, yaw) = anim.update(&art.model, fi, clip, rate, t, pos, yaw);
        let grown = grown(stage);
        let frame = (app.shape("frame") * grown.max(0.3)).clamp(-1.0, 1.0);
        let walking = posture.walking && clip.starts_with("walk");
        let duration = anim.playing.and_then(|(_, c)| c).map_or(1.0, |c| art.model.clips[c].duration.max(0.01));
        let ctx = Life { t, walking, stride: anim.phase / duration, idle: clip.starts_with("idle"), frame, demeanor, stage };
        life(&mut anim.pose, &art.rig, &ctx);
        let face = expression(clip, posture, demeanor, t, stage);
        anim.ease_face(face, dt);
        let pose = &anim.pose;
        let mut mats = Vec::with_capacity(skel.joints.len());
        skel.skin_matrices(pose, &mut mats);
        let (skinned, joints) = out;
        let pose_id = hearth_render::push_pose(joints, &mats);

        // masculine frames stand a little taller than feminine ones
        let scale = stage.height() / art.height.max(0.01) * app.height * (1.0 + 0.035 * frame * grown);
        let model = Mat4::from_translation(pos) * Mat4::from_rotation_y(yaw) * Mat4::from_scale(Vec3::splat(scale));
        let mut palette = [[1.0f32; 4]; PALETTE_SLOTS];
        let rgb = |c: [f32; 3]| [c[0], c[1], c[2], 1.0];
        palette[slot::SKIN as usize] = rgb(app.skin);
        palette[slot::HAIR as usize] = rgb(app.hair);
        palette[slot::SHIRT as usize] = rgb(app.shirt);
        palette[slot::PANTS as usize] = rgb(app.pants);
        palette[slot::SHOES as usize] = rgb(app.shoes);
        palette[slot::IRIS as usize] = rgb(app.eyes);
        let outfit = outfit(stage, app);
        let hide = outfit.iter().flat_map(|g| covers(g)).fold(0u32, |m, r| m | 1 << r);
        let face = anim.face;
        let draw = |p: &Part, roughness: f32| {
            let mut d = SkinnedDraw::new(p.mesh, pose_id, model, palette);
            d.morph = morph_weights(&p.morphs, stage, app, &face);
            d.roughness = roughness;
            d
        };
        let mut draws = vec![draw(&art.body, 0.7), draw(&art.head, 0.6)];
        draws[0].hide = hide;
        draws.extend(outfit.iter().filter_map(|g| art.parts.get(g.as_str())).map(|p| draw(p, 0.85)));
        for (prefix, id) in hairdo(stage, app) {
            if let Some(p) = art.parts.get(&format!("{prefix}.{id}")) {
                draws.push(draw(p, 0.55));
            }
        }
        for mut d in draws {
            if look == Look::Ghost {
                for c in &mut d.palette {
                    *c = [c[0] * 0.3 + 0.55, c[1] * 0.3 + 0.7, c[2] * 0.3 + 0.75, 1.0];
                }
                d.color[3] = 0.38;
                d.emissive = 0.6;
                d.flags |= hearth_render::flags::NO_SHADOW_CAST;
            }
            skinned.push(d);
        }

        // top of the head: the head joint's posed height plus its rest distance to the crown
        let globals = skel.globals(pose);
        let head_y = art.head_joint.map_or(art.head_rest_y, |j| globals[j].w_axis.y);
        let crown = if posture.pose == Pose::Lie { head_y + 0.1 } else { head_y + (art.height - art.head_rest_y) };
        let grips = art.grips.map(|g| g.map_or(model, |(j, off)| model * globals[j] * off));
        Drawn { crown: crown * scale, acting, grips }
    }
}

/// Garment meshes worn: a top (a dress replaces the bottom), a bottom and shoes.
fn outfit(_stage: LifeStage, app: &Appearance) -> Vec<String> {
    use sim::genetics::{BOTTOMS, DRESS, TOPS};
    let top = TOPS[app.top as usize % TOPS.len()].0;
    let mut out = vec![format!("top_{top}")];
    if app.top != DRESS {
        out.push(format!("bottom_{}", BOTTOMS[app.bottom as usize % BOTTOMS.len()].0));
    }
    out.push("shoes".into());
    out
}

/// Hair and facial-hair meshes as (prefix, id): beards only from young adult on.
fn hairdo(stage: LifeStage, app: &Appearance) -> Vec<(&'static str, &'static str)> {
    use sim::genetics::{FACIAL_HAIR, HAIR_STYLES};
    let mut out = vec![("hair", HAIR_STYLES[app.hair_style as usize % HAIR_STYLES.len()].0)];
    if stage.is_adult() && app.facial_hair > 0 {
        out.push(("facial", FACIAL_HAIR[app.facial_hair as usize % FACIAL_HAIR.len()].0));
    }
    out
}

/// How far a body has grown into its adult frame and chest (they fade in through the teens).
fn grown(stage: LifeStage) -> f32 {
    match stage {
        LifeStage::Infant | LifeStage::Toddler => 0.0,
        LifeStage::Child => 0.15,
        LifeStage::Teen => 0.7,
        _ => 1.0,
    }
}

/// Facial expression shape keys (head and hair meshes), in [`Face`] order.
pub const EXPRESSIONS: [&str; 7] = ["x_smile", "x_frown", "x_open", "x_blink", "x_brow_up", "x_brow_angry", "x_brow_sad"];

/// Expression weights, indexed like [`EXPRESSIONS`].
pub type Face = [f32; 7];

/// Morph weights for a mesh's targets: `slim`/`heavy` from build, expressions from `face`, the
/// rest from the shape sliders.
fn morph_weights(names: &[String], stage: LifeStage, app: &Appearance, face: &Face) -> [f32; hearth_render::MAX_MORPHS] {
    let grown = grown(stage);
    let mut w = [0.0; hearth_render::MAX_MORPHS];
    for (slot, n) in w.iter_mut().zip(names) {
        if let Some(k) = EXPRESSIONS.iter().position(|x| x == n) {
            *slot = face[k];
            continue;
        }
        *slot = match n.as_str() {
            "slim" => ((0.5 - app.build) * 2.0).clamp(0.0, 1.0),
            "heavy" => ((app.build - 0.5) * 2.0).clamp(0.0, 1.0),
            "frame" => app.shape(n) * grown.max(0.3),
            "bust" => app.shape(n).max(-0.5) * grown,
            id => app.shape(id),
        }
        .clamp(-1.0, 1.0);
    }
    w
}

/// The face a peon pulls: from what they are doing (talking, laughing, arguing, sleeping…) and
/// their mood, plus blinks, talking jaw and the odd smile. Values are targets; [`AnimState`]
/// eases towards them.
fn expression(clip: &str, posture: &Posture, demeanor: Demeanor, t: f32, stage: LifeStage) -> Face {
    let [mut smile, mut frown, mut open, mut blink, mut brow_up, mut angry, mut sad] = [0.0f32; 7];
    // speech: an irregular open-close of the jaw
    let chatter = |t: f32, amount: f32| amount * (0.5 + 0.5 * (t * 11.0).sin() * (t * 4.3 + 1.0).sin()).max(0.0);
    match demeanor {
        Demeanor::Normal => smile = 0.15,
        Demeanor::Sad => {
            frown = 0.65;
            sad = 0.85;
        }
        Demeanor::Proud => {
            smile = 0.45;
            brow_up = 0.25;
        }
        Demeanor::Nervous => {
            sad = 0.45;
            brow_up = 0.35;
            frown = 0.15;
        }
    }
    match clip {
        "laugh" => {
            smile = 1.0;
            open = 0.35 + 0.35 * (t * 9.0).sin().abs();
            brow_up = 0.4;
            sad = 0.0;
            frown = 0.0;
            blink = 0.3;
        }
        "talk" | "phone_call" | "orate" | "selfie" => {
            open = chatter(t, 0.5);
            brow_up += 0.25 * (t * 1.7).sin().max(0.0);
        }
        "argue" | "kick" => {
            angry = 1.0;
            frown = 0.7;
            smile = 0.0;
            sad = 0.0;
            open = chatter(t, 0.65);
        }
        "hug" | "cradle" | "peekaboo" | "admire" => {
            smile = 0.8;
            sad = 0.0;
            frown = 0.0;
            blink = 0.2;
        }
        "mourn" | "idle_sad" => {
            frown = 0.9;
            sad = 1.0;
            smile = 0.0;
            blink = 0.25;
        }
        "dance" | "exercise" | "play_floor" => {
            smile = smile.max(0.6);
            open = 0.25;
        }
        "sleep" | "lie" | "bathe" => blink = 1.0,
        _ => {}
    }
    if posture.pose == sim::data::Pose::Lie && clip != "lie" {
        blink = blink.max(0.0);
    }
    // babies babble with a happy face when nothing is wrong
    if stage == LifeStage::Infant && demeanor == Demeanor::Normal {
        smile = smile.max(0.4);
    }
    // a blink every few seconds (the clock carries a per-peon offset)
    if blink < 1.0 {
        let phase = (t / 3.7).fract();
        if (0.5..0.545).contains(&phase) {
            blink = 1.0;
        }
    }
    [smile, frown, open, blink, brow_up, angry, sad].map(|v| v.clamp(0.0, 1.0))
}

/// What the procedural layer needs to know about the moment.
struct Life {
    t: f32,
    walking: bool,
    /// Stride position, 0..1 through the walk clip (0 = left foot forward).
    stride: f32,
    idle: bool,
    /// Masculine (+) / feminine (-) frame, already scaled by growth.
    frame: f32,
    demeanor: Demeanor,
    stage: LifeStage,
}

/// Rotates a joint about one of its own axes (post-multiplied, so in the bone's local frame;
/// the spine and head bones point up, so local Y is the body's vertical and local X its width).
fn turn(pose: &mut JointPose, j: Option<usize>, q: Quat) {
    if let Some(j) = j
        && let Some(p) = pose.get_mut(j)
    {
        p.r *= q;
    }
}

/// The layer that keeps bodies from looking like mannequins: the skeleton follows the frame
/// (shoulder and hip width), everyone breathes, idle bodies shift their weight and glance about,
/// walking bodies swing their hips against their shoulders (more on feminine frames).
fn life(pose: &mut JointPose, rig: &Rig, c: &Life) {
    use std::f32::consts::TAU;
    for &(j, d) in &rig.frame {
        if let Some(p) = pose.get_mut(j) {
            p.t += d * c.frame;
        }
    }
    let fem = (-c.frame).clamp(0.0, 1.0);
    // breathing: the chest rises and the head settles a hair against it
    let breath = (c.t * TAU / 4.2).sin();
    let deep = if c.demeanor == Demeanor::Sad { 1.6 } else { 1.0 };
    turn(pose, rig.chest, Quat::from_rotation_x((-1.2 * deep * breath).to_radians()));
    turn(pose, rig.neck, Quat::from_rotation_x((0.8 * deep * breath).to_radians()));
    if c.walking {
        let a = c.stride * TAU;
        // pelvis turns towards the leading leg and drops on the swinging side; shoulders counter
        let hips_yaw = (5.0 + 5.0 * fem) * a.cos();
        let hips_roll = (2.0 + 4.0 * fem) * (2.0 * a).sin();
        turn(pose, rig.hips, Quat::from_rotation_y(hips_yaw.to_radians()) * Quat::from_rotation_z(hips_roll.to_radians()));
        turn(pose, rig.chest, Quat::from_rotation_y((-hips_yaw * 1.6).to_radians()));
        turn(pose, rig.spine, Quat::from_rotation_z((-hips_roll * 0.6).to_radians()));
        // the head stays level and looking ahead
        turn(pose, rig.neck, Quat::from_rotation_y((hips_yaw * 0.5).to_radians()));
    } else if c.idle && c.stage != LifeStage::Infant {
        // weight shift from foot to foot, the spine balancing it
        let shift = (c.t * TAU / 7.3).sin();
        turn(pose, rig.hips, Quat::from_rotation_z((2.0 * shift).to_radians()));
        turn(pose, rig.spine, Quat::from_rotation_z((-1.6 * shift).to_radians()));
        turn(pose, rig.chest, Quat::from_rotation_z((-0.6 * shift).to_radians()));
        // glances: the head drifts between a few directions (sum of slow sines)
        let look = 9.0 * (c.t * 0.37).sin() * (c.t * 0.13 + 2.0).sin() + 4.0 * (c.t * 0.71 + 1.0).sin();
        let nod = 3.0 * (c.t * 0.29 + 0.5).sin();
        let nervous = if c.demeanor == Demeanor::Nervous { 2.0 } else { 1.0 };
        turn(pose, rig.head, Quat::from_rotation_y((look * nervous).to_radians()) * Quat::from_rotation_x(nod.to_radians()));
    }
}

/// Seconds to cross-fade from one clip to the next.
pub const BLEND_SECS: f32 = 0.3;
/// A root jump on a clip change further than this is a teleport (not eased).
const MAX_ROOT_EASE: f32 = 3.0;

/// One peon's animation playback, kept by the game between frames: the clip playing, how far
/// into it, and a cross-fade from the last pose drawn when the clip changes. The fade also eases
/// the root, because the sim snaps a peon onto a seat or bed at the moment its posture changes.
#[derive(Clone, Debug, Default)]
pub struct AnimState {
    /// Body model and clip index playing (None = rest pose); None until the first update.
    playing: Option<(usize, Option<usize>)>,
    /// Seconds into the clip (already scaled by playback rate).
    phase: f32,
    last_t: f32,
    /// Pose faded out from, and fade progress (0..1; 1 = done).
    from: JointPose,
    fade: f32,
    /// Root offset (from the old drawn position/yaw to the new) faded out with the pose.
    root_offset: Vec3,
    yaw_offset: f32,
    last_root: (Vec3, f32),
    /// Last pose produced.
    pub pose: JointPose,
    /// Facial expression (see [`EXPRESSIONS`]), eased towards the moment's target.
    pub face: Face,
    seen: u64,
}

impl AnimState {
    /// Eases the face towards `target`: expressions take a moment, blinks are quick.
    fn ease_face(&mut self, target: Face, dt: f32) {
        for (k, (f, t)) in self.face.iter_mut().zip(target).enumerate() {
            let speed = if k == 3 { 40.0 } else if k == 2 { 18.0 } else { 5.0 };
            *f += (t - *f) * (1.0 - (-dt * speed).exp());
        }
        if dt == 0.0 {
            self.face = target;
        }
    }

    /// Advances playback to `t` and writes the pose into `self.pose`. Returns the root position
    /// and yaw to draw at (eased during a fade).
    #[allow(clippy::too_many_arguments)]
    pub fn update(&mut self, model: &Model, body: usize, clip: &str, rate: f32, t: f32, pos: Vec3, yaw: f32) -> (Vec3, f32) {
        let skel = &model.skeleton;
        let clip = model.clips.iter().position(|c| c.name == clip);
        match self.playing {
            Some((b, c)) if b == body && self.pose.len() == skel.joints.len() => {
                let dt = (t - self.last_t).clamp(0.0, 0.25);
                if c != clip {
                    self.from.clone_from(&self.pose);
                    self.fade = 0.0;
                    self.phase = 0.0;
                    self.playing = Some((body, clip));
                    let (p0, y0) = self.last_root;
                    let (off, yoff) = (p0 - pos, wrap_angle(y0 - yaw));
                    (self.root_offset, self.yaw_offset) = if off.length() < MAX_ROOT_EASE { (off, yoff) } else { (Vec3::ZERO, 0.0) };
                }
                self.phase += dt * rate;
                self.fade = (self.fade + dt / BLEND_SECS).min(1.0);
            }
            // first frame, or a new body (aged up): start in sync with the clock, no fade
            _ => {
                self.playing = Some((body, clip));
                self.phase = t * rate;
                self.fade = 1.0;
                self.root_offset = Vec3::ZERO;
                self.yaw_offset = 0.0;
            }
        }
        self.last_t = t;

        self.pose.clear();
        self.pose.extend(skel.joints.iter().map(|j| j.rest));
        if let Some(c) = clip {
            model.clips[c].sample(self.phase, &mut self.pose);
        }
        let (pos, yaw) = if self.fade < 1.0 {
            let w = self.fade * self.fade * (3.0 - 2.0 * self.fade);
            for (p, f) in self.pose.iter_mut().zip(&self.from) {
                *p = f.lerp(*p, w);
            }
            (pos + self.root_offset * (1.0 - w), yaw + self.yaw_offset * (1.0 - w))
        } else {
            (pos, yaw)
        };
        self.last_root = (pos, yaw);
        (pos, yaw)
    }
}

fn wrap_angle(a: f32) -> f32 {
    use std::f32::consts::{PI, TAU};
    (a + PI).rem_euclid(TAU) - PI
}

/// Animation state for every peon on screen, keyed by entity. Call [`Animator::begin_frame`] once
/// per frame; peons not drawn in a frame are forgotten (and snap into their pose when next seen).
#[derive(Debug, Default)]
pub struct Animator {
    states: HashMap<Entity, AnimState>,
    frame: u64,
}

impl Animator {
    pub fn begin_frame(&mut self) {
        let f = self.frame;
        self.states.retain(|_, s| s.seen == f);
        self.frame += 1;
    }

    pub fn state(&mut self, e: Entity) -> &mut AnimState {
        let s = self.states.entry(e).or_default();
        s.seen = self.frame;
        s
    }
}

/// Clip name and playback rate for a posture: the interaction's own clip when this body has it,
/// else the pose's (with the demeanor's idle/walk variant). Walk cadence speeds up for shorter legs.
fn clip_for<'a>(model: &Model, stage: LifeStage, posture: &'a Posture, demeanor: Demeanor, model_height: f32) -> (&'a str, f32) {
    if !posture.walking
        && let Some(a) = posture.anim.as_deref()
        && model.clip(a).is_some()
    {
        return (a, 1.0);
    }
    let variant = |base: &'static str| -> &'static str {
        let v = match (demeanor, base) {
            (Demeanor::Sad, "walk") => "walk_sad",
            (Demeanor::Sad, "idle") => "idle_sad",
            (Demeanor::Proud, "walk") => "walk_proud",
            (Demeanor::Proud, "idle") => "idle_proud",
            (Demeanor::Nervous, "idle") => "idle_nervous",
            _ => base,
        };
        if model.clip(v).is_some() { v } else { base }
    };
    let stride = (1.75 / model_height.max(0.3)).sqrt().min(1.6);
    match posture.pose {
        Pose::Stand if posture.walking => {
            let w = variant("walk");
            let pace = match w {
                "walk_sad" => 0.8,
                "walk_proud" => 0.95,
                _ => 1.0,
            };
            (w, 1.1 * stride * pace * if stage == LifeStage::Elder { 0.85 } else { 1.0 })
        }
        Pose::Stand => (variant("idle"), 1.0),
        Pose::Sit => ("sit", 1.0),
        Pose::Lie => ("lie", 1.0),
        Pose::Use => ("use", 1.0),
        Pose::Dance => ("dance", 0.9),
        Pose::Exercise => ("exercise", 0.8),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_stage_model_loads_with_its_clips() {
        for (name, bytes) in FILES {
            let m = Model::load_glb(bytes, &slot_of).unwrap();
            let body = m.mesh("body").unwrap_or_else(|| panic!("{name}: body"));
            let head = m.mesh("head").unwrap_or_else(|| panic!("{name}: head"));
            for (id, _) in [("slim", ""), ("heavy", "")].iter().chain(sim::genetics::BODY_SLIDERS.iter()) {
                assert!(body.morph(id).is_some(), "{name}: body morph {id}");
            }
            for (id, _) in sim::genetics::FACE_SLIDERS {
                assert!(head.morph(id).is_some(), "{name}: head morph {id}");
            }
            let all = || m.meshes.iter().flat_map(|m| m.data.vertices.iter());
            for s in [slot::SKIN, slot::HAIR, slot::SHIRT, slot::PANTS, slot::SHOES, slot::IRIS] {
                assert!(all().any(|v| v.slot & 0xff == s), "{name}: slot {s}");
            }
            for r in 1..=region::FOOT {
                assert!(body.data.vertices.iter().any(|v| v.slot >> 8 == r), "{name}: skin region {r}");
            }
            for (id, _) in sim::genetics::HAIR_STYLES.iter().filter(|(id, _)| *id != "bald") {
                assert!(m.mesh(&format!("hair.{id}")).is_some(), "{name}: hair.{id}");
            }
            for (id, _) in sim::genetics::FACIAL_HAIR.iter().skip(1) {
                assert!(m.mesh(&format!("facial.{id}")).is_some(), "{name}: facial.{id}");
            }
            for app in outfits() {
                for g in outfit(LifeStage::Adult, &app) {
                    assert!(m.mesh(&g).is_some(), "{name}: garment {g}");
                }
            }
            for c in ["idle", "walk", "sit", "lie", "use", "dance", "exercise"] {
                assert!(m.clip(c).is_some(), "{name}: clip {c}");
            }
            let top = head.data.vertices.iter().map(|v| v.pos[1]).fold(0.0, f32::max);
            let want = LifeStage::ALL[match name {
                "infant" => 0,
                "toddler" => 1,
                "child" => 2,
                "teen" => 3,
                "adult" => 5,
                _ => 6,
            }]
            .height();
            assert!((top - want).abs() < want * 0.05, "{name}: model height {top}, stage height {want}");
        }
    }

    #[test]
    fn every_clip_the_data_names_exists_on_the_bodies_that_play_it() {
        let data = sim::data::GameData::embedded();
        for stage in LifeStage::ALL {
            let (name, bytes) = FILES[file_index(stage)];
            let moods: &[&str] = if stage.can_walk() { &["idle_sad", "walk_sad", "idle_proud", "walk_proud", "idle_nervous"] } else { &["idle_sad"] };
            let wanted: Vec<&str> = data.anims_for(stage).into_iter().chain(moods.iter().copied()).collect();
            let m = Model::load_glb(bytes, &slot_of).unwrap();
            let missing: Vec<_> = wanted.iter().filter(|c| m.clip(c).is_none()).collect();
            assert!(missing.is_empty(), "peon_{name}.glb ({stage:?}) lacks clips {missing:?}");
        }
    }

    #[test]
    fn interaction_clip_wins_and_falls_back_to_the_pose() {
        let m = adult();
        let mut p = Posture::performing(Pose::Use, Some("stir".into()), None);
        assert_eq!(clip_for(&m, LifeStage::Adult, &p, Demeanor::Normal, 1.75).0, "stir");
        p.anim = Some("no_such_clip".into());
        assert_eq!(clip_for(&m, LifeStage::Adult, &p, Demeanor::Normal, 1.75).0, "use");
        let walking = Posture { walking: true, ..Default::default() };
        assert_eq!(clip_for(&m, LifeStage::Adult, &walking, Demeanor::Sad, 1.75).0, "walk_sad");
    }

    #[test]
    fn grips_follow_the_hands() {
        let m = adult();
        let skel = &m.skeleton;
        let j = skel.joint("hand.R").unwrap();
        let off = grip_offset(skel, j, 1.75);
        let rest = skel.globals(&skel.rest_pose())[j] * off;
        // palm a little below and outside the wrist on the right (-x), grip z facing forward
        let wrist = skel.globals(&skel.rest_pose())[j].w_axis.truncate();
        let palm = rest.w_axis.truncate();
        assert!(palm.y < wrist.y && palm.x < wrist.x, "palm {palm} wrist {wrist}");
        assert!(rest.z_axis.truncate().dot(Vec3::Z) > 0.9);
    }

    fn outfits() -> Vec<Appearance> {
        let n = sim::genetics::TOPS.len().max(sim::genetics::BOTTOMS.len());
        (0..n).map(|i| Appearance { top: i as u8 % sim::genetics::TOPS.len() as u8, bottom: i as u8 % sim::genetics::BOTTOMS.len() as u8, ..Default::default() }).collect()
    }

    #[test]
    fn material_names_map_to_slots_and_regions() {
        assert_eq!(slot_of("skin"), slot::SKIN);
        assert_eq!(slot_of("skin.lips"), slot::SKIN);
        assert_eq!(slot_of("skin.r7"), slot::SKIN | 7 << 8);
        assert_eq!(slot_of("shirt"), slot::SHIRT);
        assert_eq!(slot_of("eye_white"), 0);
    }

    #[test]
    fn clothes_hide_the_skin_they_cover() {
        let dress = Appearance { top: sim::genetics::DRESS, bottom: 0, ..Default::default() };
        assert_eq!(outfit(LifeStage::Adult, &dress), ["top_dress", "shoes"], "a dress replaces the bottom");
        let tee = Appearance { top: 0, bottom: 1, ..Default::default() };
        let o = outfit(LifeStage::Adult, &tee);
        assert_eq!(o, ["top_tee", "bottom_shorts", "shoes"]);
        let covered: Vec<u32> = o.iter().flat_map(|g| covers(g).iter().copied()).collect();
        assert!(covered.contains(&region::CHEST) && covered.contains(&region::THIGH) && covered.contains(&region::FOOT));
        assert!(!covered.contains(&region::FOREARM) && !covered.contains(&region::SHIN), "arms and calves show");
    }

    #[test]
    fn sliders_drive_morph_weights_and_kids_grow_into_their_frame() {
        let mut app = Appearance { build: 0.8, ..Default::default() };
        app.shape.insert("jaw".into(), 0.6);
        app.shape.insert("bust".into(), 0.9);
        let names: Vec<String> = ["slim", "heavy", "jaw", "bust", "nose_tip"].iter().map(|s| s.to_string()).collect();
        let w = morph_weights(&names, LifeStage::Adult, &app, &Face::default());
        assert_eq!(w[..5], [0.0, 0.6f32.min((0.8 - 0.5) * 2.0), 0.6, 0.9, 0.0]);
        let kid = morph_weights(&names, LifeStage::Child, &app, &Face::default());
        assert!(kid[3] < 0.2, "no chest on a child: {}", kid[3]);
        assert_eq!(kid[2], 0.6, "faces show at every age");
        app.facial_hair = 5;
        assert_eq!(hairdo(LifeStage::Teen, &app).len(), 1, "no beards before young adult");
        assert_eq!(hairdo(LifeStage::Adult, &app).len(), 2);
    }

    #[test]
    fn faces_follow_mood_and_action() {
        let idle = Posture::default();
        let talk = Posture::performing(Pose::Stand, Some("talk".into()), None);
        let sad = expression("idle_sad", &idle, Demeanor::Sad, 1.0, LifeStage::Adult);
        assert!(sad[1] > 0.5 && sad[6] > 0.5, "frown and worried brows: {sad:?}");
        let laugh = expression("laugh", &idle, Demeanor::Normal, 1.0, LifeStage::Adult);
        assert!(laugh[0] > 0.9 && laugh[2] > 0.3);
        let argue = expression("argue", &idle, Demeanor::Normal, 1.0, LifeStage::Adult);
        assert!(argue[5] > 0.9 && argue[0] == 0.0);
        let opens = (0..100).map(|i| expression("talk", &talk, Demeanor::Normal, i as f32 * 0.05, LifeStage::Adult)[2]);
        let (lo, hi) = opens.fold((1.0f32, 0.0f32), |(lo, hi), v| (lo.min(v), hi.max(v)));
        assert!(lo < 0.1 && hi > 0.3, "the jaw moves while talking: {lo}..{hi}");
        assert_eq!(expression("sleep", &idle, Demeanor::Normal, 0.5, LifeStage::Adult)[3], 1.0);
        let blinks = (0..400).filter(|i| expression("idle", &idle, Demeanor::Normal, *i as f32 * 0.05, LifeStage::Adult)[3] > 0.5).count();
        assert!(blinks > 0 && blinks < 40, "blinks now and then: {blinks}");
    }

    #[test]
    fn frame_moves_the_shoulders_and_hips() {
        let m = adult();
        let rig = Rig::new(&m.skeleton, 1.75);
        let width = |frame: f32| {
            let mut pose = m.skeleton.rest_pose();
            let c = Life { t: 0.0, walking: false, stride: 0.0, idle: false, frame, demeanor: Demeanor::Normal, stage: LifeStage::Adult };
            life(&mut pose, &rig, &c);
            let g = m.skeleton.globals(&pose);
            let x = |n: &str| g[m.skeleton.joint(n).unwrap()].w_axis.x;
            (x("upper_arm.L") - x("upper_arm.R"), x("thigh.L") - x("thigh.R"))
        };
        let (m_sh, m_hip) = width(1.0);
        let (f_sh, f_hip) = width(-1.0);
        assert!(m_sh > f_sh + 0.04, "broader shoulders: {m_sh} vs {f_sh}");
        assert!(f_hip > m_hip + 0.03, "wider hips: {f_hip} vs {m_hip}");
    }

    #[test]
    fn walking_hips_sway_more_on_feminine_frames() {
        let m = adult();
        let rig = Rig::new(&m.skeleton, 1.75);
        let sway = |frame: f32| {
            let mut pose = m.skeleton.rest_pose();
            let c = Life { t: 0.0, walking: true, stride: 0.0, idle: false, frame, demeanor: Demeanor::Normal, stage: LifeStage::Adult };
            life(&mut pose, &rig, &c);
            pose[rig.hips.unwrap()].r.angle_between(m.skeleton.rest_pose()[rig.hips.unwrap()].r)
        };
        assert!(sway(-1.0) > sway(1.0) * 1.5);
    }

    fn adult() -> Model {
        Model::load_glb(FILES[4].1, &slot_of).unwrap()
    }

    fn hips_y(m: &Model, pose: &JointPose) -> f32 {
        m.skeleton.globals(pose)[m.skeleton.joint("hips").unwrap()].w_axis.y
    }

    #[test]
    fn clip_change_cross_fades_pose_and_root() {
        let m = adult();
        let mut a = AnimState::default();
        let floor = Vec3::new(2.0, 0.0, 2.0);
        let seat = Vec3::new(2.5, 0.45, 2.0);
        let mut t = 10.0;
        a.update(&m, 4, "idle", 1.0, t, floor, 0.0);
        let standing = hips_y(&m, &a.pose);

        // the sim snaps onto the seat as the posture changes: the first frame still looks standing
        t += 1.0 / 60.0;
        let (p, _) = a.update(&m, 4, "sit", 1.0, t, seat, 1.0);
        assert!((hips_y(&m, &a.pose) - standing).abs() < 0.02, "no pop into the sit pose");
        assert!(p.distance(floor) < 0.02, "root eased from where it was drawn: {p}");

        // halfway through the fade: in between
        t += BLEND_SECS * 0.5;
        let (p, _) = a.update(&m, 4, "sit", 1.0, t, seat, 1.0);
        let mut sitting = m.skeleton.rest_pose();
        m.clip("sit").unwrap().sample(t - 10.0, &mut sitting);
        let (mid, sat) = (hips_y(&m, &a.pose), hips_y(&m, &sitting));
        assert!(mid < standing - 0.05 && mid > sat + 0.05, "hips {mid} between {standing} and {sat}");
        assert!(p.distance(floor) > 0.1 && p.distance(seat) > 0.1, "root between: {p}");

        // after it: fully seated, root on the seat
        t += BLEND_SECS;
        let (p, yaw) = a.update(&m, 4, "sit", 1.0, t, seat, 1.0);
        let mut sitting = m.skeleton.rest_pose();
        m.clip("sit").unwrap().sample(a.phase, &mut sitting);
        assert_eq!(a.pose, sitting);
        assert_eq!((p, yaw), (seat, 1.0));
    }

    #[test]
    fn fresh_state_poses_from_the_clock_and_teleports_snap() {
        let m = adult();
        let mut a = AnimState::default();
        a.update(&m, 4, "walk", 1.3, 7.0, Vec3::ZERO, 0.0);
        let mut want = m.skeleton.rest_pose();
        m.clip("walk").unwrap().sample(7.0 * 1.3, &mut want);
        assert_eq!(a.pose, want);
        // coming home from across the map: the root jumps, not slides
        let far = Vec3::new(20.0, 0.0, 0.0);
        let (p, _) = a.update(&m, 4, "idle", 1.0, 7.02, far, 0.0);
        assert_eq!(p, far);
    }

    #[test]
    fn animator_forgets_peons_not_drawn() {
        let mut w = hearth_ecs::World::new();
        let (e1, e2) = (w.spawn_empty(), w.spawn_empty());
        let mut an = Animator::default();
        an.begin_frame();
        an.state(e1).phase = 1.0;
        an.state(e2).phase = 2.0;
        an.begin_frame();
        an.state(e1);
        an.begin_frame();
        assert_eq!(an.states.len(), 1);
        assert_eq!(an.state(e1).phase, 1.0);
        assert_eq!(an.state(e2).phase, 0.0);
    }
}
